task apps_2933__solve(nums: seq, div: int) returns (r: seq)
  requires div > 0
  ensures len(r) == len(nums)
  ensures forall i in [0, len(nums)) . r[i] == nums[i] + nums[i] % div
{
  r := [];
  var i: int := 0;
  while i < len(nums)
    invariant 0 <= i
    invariant i <= len(nums)
    invariant len(r) == i
    invariant forall j in [0, i) . r[j] == nums[j] + nums[j] % div
    decreases len(nums) - i
  {
    r := r + [nums[i] + nums[i] % div];
    i := i + 1;
  }
}

